import { useState } from 'react';
import quizData from '../utils/quizData';

const useQuizLogic = () => {
    const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    const [userAnswers, setUserAnswers] = useState([]);
    const [score, setScore] = useState(0);

    const [feedback, setFeedback] = useState(null); // New feedback state

    const currentQuestion = quizData[currentQuestionIndex];

    const handleAnswerSelection = (answer) => {
        setUserAnswers([...userAnswers, answer]);
        if (answer === currentQuestion.correct) {
            setScore(score + 1);
            setFeedback("Correct! 🎉");
        } else {
            setFeedback(`Wrong! The correct answer is "${currentQuestion.correct}". 😞`);
        }
        setTimeout(() => {
            setFeedback(null); // Clear feedback after 2 seconds
            setCurrentQuestionIndex(currentQuestionIndex + 1);
        }, 2000);
    };

    const resetQuiz = () => {
        setCurrentQuestionIndex(0);
        setUserAnswers([]);
        setScore(0);
        setFeedback(null);
    };

    return {
        currentQuestion,
        currentQuestionIndex,
        userAnswers,
        score,
        feedback, // Return feedback
        handleAnswerSelection,
        resetQuiz,
        isQuizFinished: currentQuestionIndex >= quizData.length,
    };
};

export default useQuizLogic;
